$out = Join-Path $PWD 'run-obfuscator.out.log'; $err = Join-Path $PWD 'run-obfuscator.err.log'; Remove-Item -LiteralPath $out,$err -ErrorAction SilentlyContinue; $p = Start-Process -FilePath 'java' -ArgumentList '-jar','target\XellObfuscator-1.0-SNAPSHOT-jar-with-dependencies.jar' -WorkingDirectory $PWD -RedirectStandardOutput $out -RedirectStandardError $err -PassThru -WindowStyle Hidden; Start-Sleep -Seconds 35; if (-not $p.HasExited) { Stop-Process -Id $p.Id -Force; Start-Sleep -Seconds 1 }; Write-Output "exit=$($p.ExitCode)"; Write-Output 'size:'; (Get-Item Xell.out.lua -ErrorAction SilentlyContinue).Length; Write-Output 'stdout:'; Get-Content -Path $out -ErrorAction SilentlyContinue; Write-Output 'stderr:'; Get-Content -Path $err -ErrorAction SilentlyContinue